#!/data/data/com.termux/files/usr/bin/bash
# Fixes black corners on launcher icon by replacing with a transparent,
# tightly-cropped, high-quality version at all densities.
set -e

if [ ! -d "app/src/main/res" ]; then
  echo "ERROR: run this from project root (where app/ folder is)"
  exit 1
fi

echo "Writing fixed launcher icons (no black corners, transparent bg)..."
mkdir -p app/src/main/res/mipmap-mdpi
base64 -d > app/src/main/res/mipmap-mdpi/ic_launcher.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-mdpi
base64 -d > app/src/main/res/mipmap-mdpi/ic_launcher_round.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-hdpi
base64 -d > app/src/main/res/mipmap-hdpi/ic_launcher.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-hdpi
base64 -d > app/src/main/res/mipmap-hdpi/ic_launcher_round.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-xhdpi
base64 -d > app/src/main/res/mipmap-xhdpi/ic_launcher.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-xhdpi
base64 -d > app/src/main/res/mipmap-xhdpi/ic_launcher_round.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-xxhdpi
base64 -d > app/src/main/res/mipmap-xxhdpi/ic_launcher.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-xxhdpi
base64 -d > app/src/main/res/mipmap-xxhdpi/ic_launcher_round.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-xxxhdpi
base64 -d > app/src/main/res/mipmap-xxxhdpi/ic_launcher.png << 'ICONEOF'

ICONEOF
mkdir -p app/src/main/res/mipmap-xxxhdpi
base64 -d > app/src/main/res/mipmap-xxxhdpi/ic_launcher_round.png << 'ICONEOF'

ICONEOF

echo "Done: launcher icons updated, black corners removed."
